WITH with_gaps AS (SELECT *, CASE WHEN LAG(started_at) OVER (PARTITION BY country ORDER BY started_at, id) IS NULL OR started_at > LAG(started_at) OVER (PARTITION BY country ORDER BY started_at, id) + INTERVAL '90' DAY THEN 1 ELSE 0 END AS is_new_session FROM sessions), islands AS (SELECT id, customer_id, device, started_at, country, SUM(is_new_session) OVER (PARTITION BY country ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_id FROM with_gaps) SELECT id, country, session_id FROM islands ORDER BY id DESC NULLS LAST, country LIMIT 20
